-- Logos are explicitly provisioned/audited by 022, not created by 021.
-- Missing logos policies do not prove partial 021 execution. Use 022 postflight.
-- 021 security remediation. Manual execution in a fresh SQL Editor session.
-- Strictly read-only: no DDL/DML, temp objects, role/origin changes or table locks.
-- Preserve and compare IDs/paths plus a manual object/blob inventory before/after.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
-- Detect legacy 011 objects created outside public (011 used unqualified names).
SELECT current_user,session_user,current_setting('search_path') search_path;
SELECT n.nspname schema,c.relname,c.relkind,pg_get_userbyid(c.relowner) owner,
 c.relrowsecurity,c.relforcerowsecurity,has_schema_privilege(current_user,n.oid,'USAGE') schema_usage,
 has_table_privilege(current_user,c.oid,'SELECT') can_select,
 pg_has_role(current_user,c.relowner,'USAGE') owner_role_usage
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE c.relname IN ('fichas_epi','fichas_epi_itens') ORDER BY n.nspname,c.relname;

SELECT schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies
 WHERE (schemaname='public' AND tablename IN ('empresas','documentos','user_profiles','colaboradores',
 'funcoes','setores','ambientes','treinamentos','matriz_treinamentos','treinamento_tipos'))
 OR (schemaname='storage' AND tablename='objects') ORDER BY schemaname,tablename,policyname;
SELECT p.oid::regprocedure signature,p.proconfig,p.proacl,pg_get_userbyid(p.proowner) owner,pg_get_functiondef(p.oid) definition
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='engmarq_private'
 OR (n.nspname='public' AND p.proname IN ('get_user_empresa_id','get_user_role')) ORDER BY p.oid::regprocedure::text;
SELECT t.tgrelid::regclass relation,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid) definition FROM pg_trigger t
 WHERE t.tgrelid IN (to_regclass('public.empresas'),to_regclass('public.documentos')) AND NOT t.tgisinternal;
SELECT k.conrelid::regclass relation,k.conname,k.convalidated,pg_get_constraintdef(k.oid) definition FROM pg_constraint k
 WHERE k.conrelid IN (to_regclass('public.documentos'),to_regclass('public.colaboradores'));
SELECT c.oid::regclass relation,c.relrowsecurity,c.reloptions,c.relacl,pg_get_userbyid(c.relowner) owner FROM pg_class c
 WHERE c.oid IN (to_regclass('public.empresas'),to_regclass('public.documentos'),to_regclass('public.vw_dashboard_documentos'),
 to_regclass('storage.objects'),to_regclass('storage.buckets'));
SELECT id,empresa_id,colaborador_id,arquivo_url,arquivo_path FROM public.documentos ORDER BY id;
SELECT id,bucket_id,name,metadata FROM storage.objects WHERE bucket_id IN ('documentos') ORDER BY id;
SELECT id,public,file_size_limit,allowed_mime_types FROM storage.buckets WHERE id IN ('documentos');
WITH
required(relation) AS (VALUES ('public.empresas'),('public.documentos'),('public.colaboradores'),('public.user_profiles'),
 ('public.treinamentos'),('public.funcoes'),('public.setores'),('public.ambientes'),('public.matriz_treinamentos'),('public.treinamento_tipos'),
 ('public.vw_dashboard_treinamentos'),('public.vw_dashboard_documentos'),('storage.objects'),('storage.buckets')),
auditor_relations AS (
 SELECT r.relation,c.oid,pg_get_userbyid(c.relowner) owner,
 CASE WHEN c.oid IS NULL THEN 'relation_missing'
 WHEN NOT has_schema_privilege(current_user,n.oid,'USAGE') THEN 'schema_usage_denied'
 WHEN NOT has_table_privilege(current_user,c.oid,'SELECT') THEN 'select_denied'
 WHEN c.relrowsecurity AND NOT (u.rolbypassrls OR u.rolsuper OR
   (pg_has_role(current_user,c.relowner,'USAGE') AND NOT c.relforcerowsecurity)) THEN 'rls_filtered'
 ELSE 'ok' END reason
 FROM required r LEFT JOIN pg_class c ON c.oid=to_regclass(r.relation)
 LEFT JOIN pg_namespace n ON n.oid=c.relnamespace
 JOIN pg_roles u ON u.rolname=current_user
),
ready AS (SELECT bool_and(reason='ok') ok FROM auditor_relations),
document_ready AS (SELECT bool_and(reason='ok') ok FROM auditor_relations
 WHERE relation IN ('public.documentos','public.colaboradores','storage.objects','storage.buckets')),
inventory AS (SELECT CASE WHEN (SELECT ok FROM document_ready) THEN query_to_xml($data$
 SELECT (SELECT count(*) FROM public.documentos) documentos,
 (SELECT count(*) FROM public.documentos WHERE arquivo_url IS NOT NULL) legacy,
 (SELECT count(*) FROM public.documentos WHERE arquivo_path IS NOT NULL) canonical,
 (SELECT count(*) FROM public.documentos WHERE arquivo_url IS NOT NULL AND arquivo_path IS NULL) pending,
 (SELECT count(*) FROM storage.objects WHERE bucket_id='documentos') objects,
 (SELECT count(*) FROM storage.objects WHERE bucket_id='documentos' AND (metadata->>'mimetype' IS NULL
   OR metadata->>'mimetype' NOT IN ('application/pdf','application/msword',
   'application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel',
   'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','image/jpeg','image/png'))) bad_mime,
 (SELECT count(*) FROM storage.objects WHERE bucket_id='documentos' AND CASE
   WHEN metadata->>'size' ~ '^[0-9]+([.][0-9]+)?$' THEN (metadata->>'size')::numeric>10485760 ELSE true END) bad_size,
 (SELECT count(*) FROM public.documentos d LEFT JOIN public.colaboradores c ON c.id=d.colaborador_id
   WHERE d.colaborador_id IS NOT NULL AND (c.id IS NULL OR c.empresa_id<>d.empresa_id)) foreign_employee,
 (SELECT count(*) FROM public.documentos d WHERE d.arquivo_path IS NOT NULL AND
   (d.arquivo_path !~ ('^'||d.empresa_id::text||'/(certificados/)?[A-Za-z0-9_-]+\.[A-Za-z0-9]+$')
   OR NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='documentos' AND o.name=d.arquivo_path))) bad_path,
 (SELECT count(*) FROM public.documentos d WHERE d.arquivo_url IS NOT NULL AND
   (d.arquivo_url !~ ('^https://kkjckayiqvlqpdjyoxyv\.supabase\.co/storage/v1/object/public/documentos/'||
     d.empresa_id::text||'/(certificados/)?[A-Za-z0-9_-]+\.[A-Za-z0-9]+$')
   OR NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='documentos' AND
     o.name=substr(d.arquivo_url,length('https://kkjckayiqvlqpdjyoxyv.supabase.co/storage/v1/object/public/documentos/')+1)))) bad_legacy,
 (SELECT count(*) FROM storage.buckets WHERE id='documentos' AND NOT public AND file_size_limit=10485760
   AND cardinality(allowed_mime_types)=7 AND allowed_mime_types @> ARRAY['application/pdf','application/msword',
   'application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel',
   'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','image/jpeg','image/png']) private_bucket
 $data$,true,false,'') ELSE '<table/>'::xml END x),
metrics(label,actual,expected) AS (
 SELECT 'Documentos preservados', (xpath('/table/row/documentos/text()',x))[1]::text,12 FROM inventory UNION ALL
 SELECT 'Legacy references preservadas',(xpath('/table/row/legacy/text()',x))[1]::text,4 FROM inventory UNION ALL
 SELECT 'Canonical references preservadas',(xpath('/table/row/canonical/text()',x))[1]::text,4 FROM inventory UNION ALL
 SELECT 'Pending backfill',(xpath('/table/row/pending/text()',x))[1]::text,0 FROM inventory UNION ALL
 SELECT 'Objetos preservados',(xpath('/table/row/objects/text()',x))[1]::text,4 FROM inventory UNION ALL
 SELECT 'MIME incompatível',(xpath('/table/row/bad_mime/text()',x))[1]::text,0 FROM inventory UNION ALL
 SELECT 'Tamanho inválido ou acima de 10 MB',(xpath('/table/row/bad_size/text()',x))[1]::text,0 FROM inventory UNION ALL
 SELECT 'Documentos vinculados a colaborador estrangeiro',(xpath('/table/row/foreign_employee/text()',x))[1]::text,0 FROM inventory UNION ALL
 SELECT 'Arquivo_path inválido ou objeto ausente',(xpath('/table/row/bad_path/text()',x))[1]::text,0 FROM inventory UNION ALL
 SELECT 'Legacy URL inválida ou objeto ausente',(xpath('/table/row/bad_legacy/text()',x))[1]::text,0 FROM inventory UNION ALL
 SELECT 'Bucket privado / 10 MB / 7 MIME',(xpath('/table/row/private_bucket/text()',x))[1]::text,1 FROM inventory
),
expected_policies AS (SELECT * FROM jsonb_to_recordset('[{"schemaname": "public", "tablename": "ambientes", "policyname": "ambientes_insert", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "INSERT", "qual": null, "with_check": "engmarq_private.can_access_catalogos(empresa_id, true)"}, {"schemaname": "public", "tablename": "ambientes", "policyname": "ambientes_select", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "SELECT", "qual": "engmarq_private.can_access_catalogos(empresa_id)", "with_check": null}, {"schemaname": "public", "tablename": "ambientes", "policyname": "ambientes_update", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "UPDATE", "qual": "engmarq_private.can_access_catalogos(empresa_id, true)", "with_check": "engmarq_private.can_access_catalogos(empresa_id, true)"}, {"schemaname": "public", "tablename": "colaboradores", "policyname": "colaboradores_insert", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "INSERT", "qual": null, "with_check": "engmarq_private.can_access_colaboradores(empresa_id, true)"}, {"schemaname": "public", "tablename": "colaboradores", "policyname": "colaboradores_select", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "SELECT", "qual": "engmarq_private.can_access_colaboradores(empresa_id)", "with_check": null}, {"schemaname": "public", "tablename": "colaboradores", "policyname": "colaboradores_update", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "UPDATE", "qual": "engmarq_private.can_access_colaboradores(empresa_id, true)", "with_check": "engmarq_private.can_access_colaboradores(empresa_id, true)"}, {"schemaname": "public", "tablename": "documentos", "policyname": "documentos_delete", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "DELETE", "qual": "engmarq_private.can_access_documento_row(empresa_id, true)", "with_check": null}, {"schemaname": "public", "tablename": "documentos", "policyname": "documentos_insert", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "INSERT", "qual": null, "with_check": "engmarq_private.can_access_documento_row(empresa_id, true)"}, {"schemaname": "public", "tablename": "documentos", "policyname": "documentos_row_guard", "permissive": "RESTRICTIVE", "roles": "{authenticated}", "cmd": "ALL", "qual": "engmarq_private.can_access_documento_row(empresa_id)", "with_check": "engmarq_private.can_access_documento_row(empresa_id, true)"}, {"schemaname": "public", "tablename": "documentos", "policyname": "documentos_select", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "SELECT", "qual": "engmarq_private.can_access_documento_row(empresa_id)", "with_check": null}, {"schemaname": "public", "tablename": "documentos", "policyname": "documentos_update", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "UPDATE", "qual": "engmarq_private.can_access_documento_row(empresa_id, true)", "with_check": "engmarq_private.can_access_documento_row(empresa_id, true)"}, {"schemaname": "public", "tablename": "empresas", "policyname": "empresas_insert", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "INSERT", "qual": null, "with_check": "engmarq_private.can_access_empresa(id, true, true)"}, {"schemaname": "public", "tablename": "empresas", "policyname": "empresas_row_guard", "permissive": "RESTRICTIVE", "roles": "{authenticated}", "cmd": "ALL", "qual": "engmarq_private.can_access_empresa(id)", "with_check": "engmarq_private.can_access_empresa(id, true)"}, {"schemaname": "public", "tablename": "empresas", "policyname": "empresas_select", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "SELECT", "qual": "engmarq_private.can_access_empresa(id)", "with_check": null}, {"schemaname": "public", "tablename": "empresas", "policyname": "empresas_update", "permissive": "PERMISSIVE", "roles": "{authenticated}", "cmd": "UPDATE", "qual": "engmarq_private.can_access_empresa(id, true)", "with_check": "engmarq_private.can_ac