": "matriz_treinamentos", "role": "authenticated", "table_privileges": "DELETE,SELECT", "insert_columns": "empresa_id,funcao_id,obrigatorio,treinamento_tipo_id", "update_columns": "obrigatorio"}, {"relation": "setores", "role": "anon", "table_privileges": "", "insert_columns": "", "update_columns": ""}, {"relation": "setores", "role": "authenticated", "table_privileges": "SELECT", "insert_columns": "active,descricao,empresa_id,nome", "update_columns": "active,descricao,nome"}, {"relation": "treinamento_tipos", "role": "anon", "table_privileges": "", "insert_columns": "", "update_columns": ""}, {"relation": "treinamento_tipos", "role": "authenticated", "table_privileges": "SELECT", "insert_columns": "", "update_columns": ""}, {"relation": "treinamentos", "role": "anon", "table_privileges": "", "insert_columns": "", "update_columns": ""}, {"relation": "treinamentos", "role": "authenticated", "table_privileges": "SELECT", "insert_columns": "carga_horaria,certificado_url,colaborador_id,data_realizacao,data_vencimento,empresa_id,instrutor,modalidade,treinamento_tipo_id", "update_columns": "carga_horaria,certificado_url,colaborador_id,data_realizacao,data_vencimento,instrutor,modalidade,treinamento_tipo_id"}, {"relation": "user_profiles", "role": "anon", "table_privileges": "", "insert_columns": "", "update_columns": ""}, {"relation": "user_profiles", "role": "authenticated", "table_privileges": "SELECT", "insert_columns": "", "update_columns": "active,role"}]'::jsonb) AS x(relation text,role text,table_privileges text,insert_columns text,update_columns text)),
actual_grants AS (SELECT c.relname relation,r.role,
 array_to_string(ARRAY(SELECT p FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p WHERE has_table_privilege(r.role,c.oid,p) ORDER BY p),',') table_privileges,
 array_to_string(ARRAY(SELECT a.attname FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped AND has_column_privilege(r.role,c.oid,a.attname,'INSERT') ORDER BY a.attname),',') insert_columns,
 array_to_string(ARRAY(SELECT a.attname FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped AND has_column_privilege(r.role,c.oid,a.attname,'UPDATE') ORDER BY a.attname),',') update_columns
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN (VALUES('authenticated'),('anon')) r(role)
 WHERE n.nspname='public' AND c.relname IN ('empresas','documentos','user_profiles','colaboradores','funcoes','setores','ambientes','treinamentos','matriz_treinamentos','treinamento_tipos')),
report AS (
 SELECT 10 ord,'Auditor: SELECT integral' label,(SELECT ok::text FROM ready)||'; current_user='||current_user||'; session_user='||session_user||'; causas='||
 coalesce((SELECT string_agg(relation||':'||reason,', ' ORDER BY relation) FROM auditor_relations WHERE reason<>'ok'),'nenhuma') result,
 CASE WHEN (SELECT ok FROM ready) THEN 'OK' ELSE 'BLOQUEIO' END status
 UNION ALL SELECT 11,'Escopo: EPI/assinaturas',
 'EPI/assinaturas fora do escopo da 021; será tratado na migração própria do módulo EPI.','ATENÇÃO'
 UNION ALL SELECT 20,label,coalesce(actual,'indisponível')||' / esperado '||expected,
 CASE WHEN actual=expected::text THEN 'OK' ELSE 'BLOQUEIO' END FROM metrics
 UNION ALL SELECT 30,'RLS: '||relation,coalesce((SELECT relrowsecurity::text FROM pg_class WHERE oid=to_regclass(relation)),'ausente'),
 CASE WHEN (SELECT relrowsecurity FROM pg_class WHERE oid=to_regclass(relation)) THEN 'OK' ELSE 'BLOQUEIO' END
 FROM required WHERE relation NOT LIKE '%vw_%' AND relation<>'storage.buckets'
 UNION ALL SELECT 31,'Treinamentos: view invoker preservada',coalesce(c.reloptions::text,'ausente'),
 CASE WHEN 'security_invoker=true'=ANY(c.reloptions) AND NOT has_table_privilege('anon',c.oid,'SELECT')
 THEN 'OK' ELSE 'BLOQUEIO' END FROM (SELECT to_regclass('public.vw_dashboard_treinamentos') oid) v LEFT JOIN pg_class c ON c.oid=v.oid
 UNION ALL SELECT 40,'Papéis funcionais sem bypass',count(*)::text,CASE WHEN count(*)=0 THEN 'OK' ELSE 'BLOQUEIO' END
 FROM pg_roles WHERE rolname IN ('anon','authenticated') AND (rolbypassrls OR rolsuper)
 UNION ALL SELECT 41,'Schema privado: ACL',coalesce(bool_and(has_schema_privilege('authenticated',oid,'USAGE')
 AND NOT has_schema_privilege('anon',oid,'USAGE') AND NOT has_schema_privilege('anon',oid,'CREATE')
 AND NOT has_schema_privilege('authenticated',oid,'CREATE')),false)::text,
 CASE WHEN coalesce(bool_and(has_schema_privilege('authenticated',oid,'USAGE') AND NOT has_schema_privilege('anon',oid,'USAGE')
 AND NOT has_schema_privilege('anon',oid,'CREATE') AND NOT has_schema_privilege('authenticated',oid,'CREATE')),false) THEN 'OK' ELSE 'BLOQUEIO' END
 FROM pg_namespace WHERE nspname='engmarq_private'
 UNION ALL SELECT 43,'Dependências 017/019/020/018',signature,
 CASE WHEN to_regprocedure(signature) IS NOT NULL THEN 'OK' ELSE 'BLOQUEIO' END
 FROM (VALUES ('engmarq_private.can_access_catalogos(uuid,boolean)'),('engmarq_private.guard_documento_reference()'),
 ('engmarq_private.guard_treinamento_write()'),('engmarq_private.documento_legacy_path(text,uuid,text)')) x(signature)
 UNION ALL SELECT 42,'PostgREST exposed schemas',coalesce(current_setting('pgrst.db_schemas',true),'verificar configuração no painel'),
 CASE WHEN 'engmarq_private'=ANY(string_to_array(replace(current_setting('pgrst.db_schemas',true),' ',''),',')) THEN 'BLOQUEIO' ELSE 'ATENÇÃO' END
 UNION ALL SELECT 900,'Homologação externa','JWTs reais / Storage API / signed URLs / bytes / implantação da API e frontend pendentes','ATENÇÃO'
 UNION ALL SELECT 901,'Identidade das linhas e objetos','Contagens não provam identidade; comparar inventários e cópias com os resultados anteriores','ATENÇÃO'
 UNION ALL SELECT 902,'Atenções restantes','URLs de assinaturas legadas, certificados ausentes/removíveis e invariantes de negócio permanecem fora desta correção','ATENÇÃO'

 UNION ALL SELECT 100,'Policy: '||e.schemaname||'.'||e.tablename||'.'||e.policyname,
 CASE WHEN p.policyname IS NULL THEN 'policy_missing' ELSE
 'present; permissive='||p.permissive||'; cmd='||p.cmd||'; roles='||p.roles::text||
 '; USING='||coalesce(p.qual,'<NULL>')||'; WITH CHECK='||coalesce(p.with_check,'<NULL>') END,
 CASE WHEN p.policyname IS NOT NULL AND p.permissive=e.permissive AND p.cmd=e.cmd AND p.roles::text=e.roles
 AND btrim(replace(coalesce(p.qual,''),E'\r\n',E'\n'))=btrim(replace(coalesce(e.qual,''),E'\r\n',E'\n'))
 AND btrim(replace(coalesce(p.with_check,''),E'\r\n',E'\n'))=btrim(replace(coalesce(e.with_check,''),E'\r\n',E'\n')) THEN 'OK' ELSE 'BLOQUEIO' END
 FROM expected_policies e LEFT JOIN pg_policies p ON (p.schemaname,p.tablename,p.policyname)=(e.schemaname,e.tablename,e.policyname)
 UNION ALL SELECT 110,'Função: '||e.signature,coalesce(p.oid::regprocedure::text,'ausente')||'; source_hash='||coalesce(md5(replace(p.prosrc,E'\r\n',E'\n')),'<NULL>')||
 '; expected_hash='||e.source_hash||'; result_type='||coalesce(p.prorettype::regtype::text,'<NULL>')||
 '; security_definer='||coalesce(p.prosecdef::text,'<NULL>')||'; volatility='||coalesce(p.provolatile::text,'<NULL>')||
 '; config='||coalesce(p.proconfig::text,'<NULL>')||'; owner='||coalesce(pg_get_userbyid(p.proowner),'<NULL>')||
 '; acl='||coalesce(p.proacl::text,'<default>')||'; authenticated_execute='||coalesce(has_function_privilege('authenticated',p.oid,'EXECUTE')::text,'<NULL>')||
 '; anon_execute='||coalesce(has_function_privilege('anon',p.oid,'EXECUTE')::text,'<NULL>'),
 CASE WHEN p.prorettype::regtype::text=e.result_type AND p.prosecdef=e.prosecdef AND p.provolatile::text=e.provolatile AND p.proconfig::text=e.proconfig
 AND md5(replace(p.prosrc,E'\r\n',E'\n'))=e.source_hash
 AND NOT pg_has_role('authenticated',p.proowner,'USAGE') AND NOT pg_has_role('anon',p.proowner,'USAGE')
 AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE')
 AND has_function_privilege('authenticated',p.oid,'EXECUTE')=(e.signature LIKE '%can_%' OR e.signature LIKE 'get_user_%')
 AND has_function_privilege('anon',p.oid,'EXECUTE')=(e.signature LIKE '%can_access_documento(text,boolean)')
 THEN 'OK' ELSE 'BLOQUEIO' END
 FROM expected_functions e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.signature)
 UNION ALL SELECT 120,'Trigger: '||e.relation||'.'||e.tgname,coalesce(pg_get_triggerdef(t.oid),'ausente'),
 CASE WHEN t.tgtype=e.tgtype AND t.tgenabled::text=e.tgenabled AND t.tgfoid=to_regprocedure(e.function_name) THEN 'OK' ELSE 'BLOQUEIO' END
 FROM expected_triggers e LEFT JOIN pg_trigger t ON t.tgrelid=to_regclass(e.relation) AND t.tgname=e.tgname
 UNION ALL SELECT 130,'Constraint: '||e.relation||'.'||e.conname,coalesce(pg_get_constraintdef(k.oid),'ausente'),
 CASE WHEN k.convalidated AND btrim(replace(pg_get_constraintdef(k.oid),E'\r\n',E'\n'))=
 btrim(replace(e.definition,E'\r\n',E'\n')) THEN 'OK' ELSE 'BLOQUEIO' END
 FROM expected_constraints e LEFT JOIN pg_constraint k ON k.conrelid=to_regclass(e.relation) AND k.conname=e.conname

 UNION ALL SELECT 140,'View documentos: invoker e grants',coalesce(c.reloptions::text,'ausente'),
 CASE WHEN c.relkind='v' AND 'security_invoker=true'=ANY(c.reloptions)
 AND has_table_privilege('authenticated',c.oid,'SELECT') AND NOT has_table_privilege('anon',c.oid,'SELECT')
 AND NOT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped
 AND (has_column_privilege('anon',c.oid,a.attname,'SELECT') OR has_column_privilege('authenticated',c.oid,a.attname,'UPDATE')
 OR has_column_privilege('authenticated',c.oid,a.attname,'INSERT'))) THEN 'OK' ELSE 'BLOQUEIO' END
 FROM (SELECT to_regclass('public.vw_dashboard_documentos') oid) v LEFT JOIN pg_class c ON c.oid=v.oid
 UNION ALL SELECT 141,'Policy adicional em '||p.schemaname||'.'||p.tablename||'.'||p.policyname,coalesce(p.qual,''),
 CASE WHEN p.schemaname='storage' THEN 'ATENÇÃO' ELSE 'BLOQUEIO' END FROM pg_policies p WHERE
 ((p.schemaname='public' AND p.tablename IN ('empresas','documentos','user_profiles','colaboradores','funcoes','setores','ambientes','treinamentos','matriz_treinamentos','treinamento_tipos'))
 OR (p.schemaname='storage' AND p.tablename='objects' AND p.policyname NOT LIKE 'assinaturas_%')) AND NOT EXISTS(SELECT 1 FROM expected_policies e
 WHERE (e.schemaname,e.tablename,e.policyname)=(p.schemaname,p.tablename,p.policyname))
 UNION ALL SELECT 150,'ACL: '||e.relation||' / '||e.role,coalesce(a.table_privileges,'ausente')||' INSERT='||coalesce(a.insert_columns,'')||' UPDATE='||coalesce(a.update_columns,''),
 CASE WHEN (a.table_privileges,a.insert_columns,a.update_columns)=(e.table_privileges,e.insert_columns,e.update_columns)
 AND (e.role<>'anon' OR NOT has_any_column_privilege(e.role,to_regclass('public.'||e.relation),'SELECT')) THEN 'OK' ELSE 'BLOQUEIO' END
 FROM expected_grants e LEFT JOIN actual_grants a ON (e.relation,e.role)=(a.relation,a.role)

), totals AS (SELECT count(*) FILTER(WHERE status='BLOQUEIO') blocks,count(*) FILTER(WHERE status='ATENÇÃO') warnings FROM report),
final AS (SELECT * FROM report UNION ALL
 SELECT 10000,'TOTAL_BLOQUEIOS',blocks::text,CASE WHEN blocks=0 THEN 'OK' ELSE 'BLOQUEIO' END FROM totals UNION ALL
 SELECT 10001,'TOTAL_ATENCOES',warnings::text,CASE WHEN warnings=0 THEN 'OK' ELSE 'ATENÇÃO' END FROM totals)
SELECT label AS "CHECK",result AS "RESULTADO",status AS "STATUS" FROM final ORDER BY ord,label;
COMMIT;
